mapper.update:
update ai_mcp_component
   set enabled = #{enabled}, revision = revision + 1, updated_at = now()
 where id = #{id}

mapper.select:
select 
  from ai_mcp_release r join ai_mcp_component c on c.id = r.component_id
 where r.id = #{id}

select 
  from ai_mcp_release r join ai_mcp_component c on c.id = r.component_id
 where c.component_key = #{key} and r.version = #{version}

mapper.update:
update ai_mcp_release
   set state = #{state}
 where id = #{releaseId} and state in ('STAGED', 'ACTIVE')

update ai_mcp_component c
   set published_version = #{version},
       publication_generation = #{expectedGeneration},
       revision = revision + 1,
       updated_at = now()
 where c.id = #{componentId}
   and publication_generation < #{expectedGeneration}
   and exists (
       select 1
         from ai_mcp_release r
        where r.component_id = c.id
          and r.version = #{version}
          and r.generation = #{expectedGeneration}
          and r.state = 'ACTIVE'
   )

mapper.select:
select count(*)
  from ai_mcp_component
 where id = #{componentId}
   and published_version = #{version}
   and publication_generation = #{expectedGeneration}

select id, mcp_id, draft_revision, config_digest, result_json, success, created_at
  from ai_mcp_test_report
 where id = #{reportId}
